"use client";

import { forwardRef, type ComponentProps } from "react";
import LegacyFilterTable from "../beautiful-ui/primitives/FilterTable";
import { BeautifulUIRoot } from "../beautiful-ui/BeautifulUIRoot";

export type FilterTableProps = NonNullable<ComponentProps<typeof LegacyFilterTable>>;

export const FilterTable = forwardRef<HTMLDivElement, FilterTableProps>((props, ref) => (
  <BeautifulUIRoot ref={ref}>
    <LegacyFilterTable {...props} />
  </BeautifulUIRoot>
));

FilterTable.displayName = "FilterTable";

export default FilterTable;

"use client";

import { useId, useRef, useState } from "react";
import { Badge, type BadgeColor } from "@/components/ui/badge";
import { FluidHoverHighlight } from "@/components/ui/fluid-hover-highlight";
import { TabsSubtle, TabsSubtleItem } from "@/components/ui/tabs-subtle";
import { useFluidHover, useRegisterFluidHoverItem } from "@/hooks/use-fluid-hover";
import { useShape } from "@/lib/shape-context";
import { cn } from "@/lib/utils";
import "../beautiful-ui.css";

export type FilterTableStatus = "todo" | "progress" | "done";
export type FilterTableFilter = "all" | FilterTableStatus;

export interface FilterTableRow {
  task: string;
  date: string;
  status: FilterTableStatus;
  owner: string;
}

export interface FilterTableProps {
  rows?: FilterTableRow[];
  filter?: FilterTableFilter;
  defaultFilter?: FilterTableFilter;
  onFilterChange?: (filter: FilterTableFilter) => void;
}

const DEFAULT_ROWS: FilterTableRow[] = [
  { task: "Restock mango sorbet", date: "Dec 03", status: "todo", owner: "Mango Moon Gelato" },
  { task: "Churn black sesame", date: "Sep 22", status: "progress", owner: "Kumo Creamery" },
  { task: "Print summer menu", date: "Jan 02", status: "todo", owner: "Coral Coast Sorbet" },
  { task: "Taste-test batch 42", date: "Nov 08", status: "progress", owner: "Maple Orbit" },
  { task: "Order waffle cones", date: "Apr 14", status: "done", owner: "Aurora Scoops" },
];

const FILTERS: Array<{ key: FilterTableFilter; label: string; tone?: string }> = [
  { key: "all", label: "All" },
  { key: "todo", label: "To do", tone: "var(--orange)" },
  { key: "progress", label: "In Progress", tone: "var(--cyan)" },
  { key: "done", label: "Completed", tone: "var(--green)" },
];

const PILLS: Record<FilterTableStatus, { label: string; color: BadgeColor }> = {
  todo: { label: "To do", color: "orange" },
  progress: { label: "In Progress", color: "cyan" },
  done: { label: "Completed", color: "green" },
};

function TaskRow({
  row,
  index,
  hover,
}: {
  row: FilterTableRow;
  index: number;
  hover: ReturnType<typeof useFluidHover>;
}) {
  const ref = useRef<HTMLTableRowElement>(null);
  useRegisterFluidHoverItem(hover.registerItem, index, ref);
  const active = hover.activeIndex === index;
  const hideBorder = hover.activeIndex !== null && (active || index === hover.activeIndex - 1);
  const pill = PILLS[row.status];

  return (
    <tr
      ref={ref}
      className={cn(
        "relative z-10 border-b text-[13px] transition-[border-color] duration-80 last:border-0",
        hideBorder ? "border-transparent" : "border-border/40",
      )}
    >
      <th scope="row" className="px-3 py-2 font-medium text-[var(--ink)]">
        <span className="block truncate" title={row.task}>
          {row.task}
        </span>
      </th>
      <td
        className={cn(
          "px-3 py-2 whitespace-nowrap tabular-nums transition-colors duration-80",
          active ? "text-[var(--ink)]" : "text-[var(--ink-2)]",
        )}
      >
        {row.date}
      </td>
      <td className="px-3 py-2 whitespace-nowrap">
        <Badge color={pill.color}>{pill.label}</Badge>
      </td>
      <td
        className={cn(
          "px-3 py-2 transition-colors duration-80",
          active ? "text-[var(--ink)]" : "text-[var(--ink-2)]",
        )}
      >
        <span className="block truncate" title={row.owner}>
          {row.owner}
        </span>
      </td>
    </tr>
  );
}

function FilterResults({ rows }: { rows: FilterTableRow[] }) {
  const ref = useRef<HTMLDivElement>(null);
  // These rows present data, so gaps must not activate an item.
  const hover = useFluidHover(ref, { gapClick: false });

  return (
    <div ref={ref} className="relative min-w-[560px]" {...hover.handlers}>
      <FluidHoverHighlight hover={hover} />
      <table className="w-full table-fixed border-collapse text-left">
        <caption className="sr-only">Tasks grouped by workflow status</caption>
        <colgroup>
          <col className="w-[38%]" />
          <col className="w-[16%]" />
          <col className="w-[22%]" />
          <col className="w-[24%]" />
        </colgroup>
        <thead>
          <tr
            className={cn(
              "relative z-10 border-b text-[12px] text-muted-foreground transition-[border-color] duration-80",
              hover.activeIndex === 0 ? "border-transparent" : "border-border/40",
            )}
          >
            <th className="px-3 py-2 font-medium">Task name</th>
            <th className="px-3 py-2 font-medium whitespace-nowrap">Date</th>
            <th className="px-3 py-2 font-medium whitespace-nowrap">Status</th>
            <th className="px-3 py-2 font-medium">Advisor</th>
          </tr>
        </thead>
        <tbody>
          {rows.map((row, index) => (
            <TaskRow key={`${row.task}-${row.date}`} row={row} index={index} hover={hover} />
          ))}
        </tbody>
      </table>
    </div>
  );
}

export default function FilterTable({
  rows = DEFAULT_ROWS,
  filter: controlledFilter,
  defaultFilter = "all",
  onFilterChange,
}: FilterTableProps = {}) {
  const shape = useShape();
  const id = useId();
  const panelId = `${id}-results`;
  const [internalFilter, setInternalFilter] = useState<FilterTableFilter>(defaultFilter);
  const filter = controlledFilter ?? internalFilter;
  const selectedIndex = Math.max(
    0,
    FILTERS.findIndex((item) => item.key === filter),
  );
  const visibleRows = rows.filter((row) => filter === "all" || row.status === filter);

  const selectFilter = (next: FilterTableFilter) => {
    if (controlledFilter === undefined) setInternalFilter(next);
    onFilterChange?.(next);
  };

  return (
    <div className="w-full max-w-[640px]">
      <TabsSubtle
        aria-label="Filter tasks by status"
        selectedIndex={selectedIndex}
        onSelect={(index) => selectFilter(FILTERS[index].key)}
        size="compact"
        className="mb-1"
      >
        {FILTERS.map((item, index) => {
          const count =
            item.key === "all" ? rows.length : rows.filter((row) => row.status === item.key).length;

          return (
            <TabsSubtleItem
              key={item.key}
              index={index}
              label={item.label}
              id={`${id}-tab-${item.key}`}
              aria-controls={panelId}
              className="focus-visible:!outline-none"
              leadingContent={
                item.tone ? (
                  <span
                    aria-hidden
                    className="size-1.5 rounded-full"
                    style={{ background: item.tone }}
                  />
                ) : undefined
              }
              trailingContent={
                <span className="min-w-4 text-center text-[11px] tabular-nums text-muted-foreground">
                  {count}
                </span>
              }
            />
          );
        })}
      </TabsSubtle>

      <p className="sr-only" aria-live="polite">
        Showing {visibleRows.length} of {rows.length} tasks
      </p>

      <div
        aria-label="Task table"
        aria-labelledby={`${id}-tab-${filter}`}
        id={panelId}
        className={cn("overflow-x-auto bg-[var(--surface)] shadow-surface-2", shape.container)}
        role="tabpanel"
        tabIndex={0}
        style={{ scrollbarWidth: "thin" }}
      >
        {/* A new filter starts with fresh row measurements and hover state. */}
        <FilterResults key={filter} rows={visibleRows} />
      </div>
    </div>
  );
}

"use client";

import "./beautiful-ui.css";
import { forwardRef, type CSSProperties, type HTMLAttributes } from "react";
import { SurfaceProvider, useSurface } from "@/lib/surface-context";
import { useShapeVariant } from "@/lib/shape-context";

export type BeautifulUIRootProps = HTMLAttributes<HTMLDivElement>;

type AdapterStyle = CSSProperties & Record<`--${string}`, string | number>;

function clampSurface(level: number) {
  return Math.max(1, Math.min(8, level));
}

function createAdapterStyle(
  substrate: number,
  surface: number,
  style?: CSSProperties,
): AdapterStyle {
  const inset = clampSurface(substrate + 1);
  const overlay = clampSurface(surface + 2);
  const raisedOverlay = clampSurface(surface + 4);

  return {
    "--page": `var(--surface-${substrate})`,
    "--canvas": `var(--surface-${substrate})`,
    "--surface": `var(--surface-${surface})`,
    "--inset": `var(--surface-${inset})`,
    "--tooltip-bg": `var(--surface-${overlay})`,
    "--overlay-surface": `var(--surface-${overlay})`,
    "--overlay-raised": `var(--surface-${raisedOverlay})`,
    ...style,
  };
}

function useBeautifulUIScope(offset = 2) {
  const substrate = useSurface();
  const surface = clampSurface(substrate + offset);
  const shape = useShapeVariant();

  return {
    shape,
    substrate,
    surface,
    style: createAdapterStyle(substrate, surface),
  };
}

/**
 * Internal compatibility boundary for the adapted primitives. It has no layout
 * box of its own: public components use it internally so consumers inherit the
 * active BoringUI theme, surface level, and radius mode without a wrapper.
 */
export const BeautifulUIRoot = forwardRef<HTMLDivElement, BeautifulUIRootProps>(
  ({ className, style, ...props }, ref) => {
    const scope = useBeautifulUIScope();

    return (
      <SurfaceProvider value={scope.surface}>
        <div
          ref={ref}
          data-bui-component=""
          data-shape={scope.shape}
          data-surface={scope.surface}
          className={["beautiful-ui", "contents", className].filter(Boolean).join(" ")}
          style={{ ...scope.style, ...style }}
          {...props}
        />
      </SurfaceProvider>
    );
  },
);

BeautifulUIRoot.displayName = "BeautifulUIRoot";

/** Applies the same BoringUI scope to content rendered in a body portal. */
export const BeautifulUIPortalRoot = forwardRef<HTMLDivElement, BeautifulUIRootProps>(
  ({ className, style, ...props }, ref) => {
    const scope = useBeautifulUIScope();

    return (
      <SurfaceProvider value={scope.surface}>
        <div
          ref={ref}
          data-bui-component=""
          data-shape={scope.shape}
          data-surface={scope.surface}
          className={["beautiful-ui", className].filter(Boolean).join(" ")}
          style={{ ...scope.style, ...style }}
          {...props}
        />
      </SurfaceProvider>
    );
  },
);

BeautifulUIPortalRoot.displayName = "BeautifulUIPortalRoot";

export default BeautifulUIRoot;

