@keyframes fade-in {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

@keyframes eq-bounce {
  0%,
  100% {
    transform: scaleY(0.35);
  }
  50% {
    transform: scaleY(1);
  }
}

.beautiful-ui .stream-tail {
  filter: blur(1.6px);
  -webkit-mask-image: linear-gradient(to right, black 20%, rgb(0 0 0 / 0.2));
  mask-image: linear-gradient(to right, black 20%, rgb(0 0 0 / 0.2));
}

.beautiful-ui .stream-caret {
  display: inline-block;
  width: 2px;
  height: 1.05em;
  margin-left: 1.5px;
  translate: 0 -0.5px;
  border-radius: 1px;
  background: var(--ink);
  vertical-align: text-bottom;
  animation: caret-blink 1s step-end infinite;
}

.beautiful-ui .stream-caret.is-streaming {
  animation: none;
}

@keyframes caret-blink {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0;
  }
}

@media (prefers-reduced-motion: reduce) {
  .beautiful-ui .stream-caret {
    animation: none;
  }

  .beautiful-ui .stream-tail {
    filter: none;
    -webkit-mask-image: none;
    mask-image: none;
  }
}

.beautiful-ui .records-filter-menu,
.beautiful-ui .insight-chart-tooltip {
  transform-origin: top left;
}

@keyframes pop-in {
  from {
    opacity: 0;
    transform: scale(0.95);
  }
  to {
    opacity: 1;
    transform: scale(1);
  }
}

@keyframes spin {
  to {
    transform: rotate(360deg);
  }
}

@keyframes pixel-on {
  0%,
  100% {
    opacity: 0.15;
  }
  18%,
  42% {
    opacity: 1;
  }
  62% {
    opacity: 0.15;
  }
}

@media (prefers-reduced-motion: reduce) {
  .beautiful-ui *,
  .beautiful-ui *::before,
  .beautiful-ui *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}
.beautiful-ui .records-header-group {
  display: flex;
  align-items: center;
  gap: 0;
  padding: 0;
}
